// ---------- YouTube Shorts ----------
// O app "Achados Decoded" (projeto Google Cloud robo-achados) envia o mesmo vídeo do Reel para o canal do YouTube.
// A chave secreta fica no cofre (youtube_client_secret); o refresh token fica na tabela config (yt_refresh).
const YT_CLIENT_ID = "467007149883-t2umi20k07g1bmvhjmu9n9hq4n1gf9v5.apps.googleusercontent.com";
const YT_REDIRECT = "https://robo-achados-painel.vercel.app/api/youtube";
const GOOGLE_TOKEN = "https://oauth2.googleapis.com/token";

// Só quem tem o convite (config.yt_convite) consegue iniciar a conexão; o "state" amarra a volta do Google.
async function youtubeConsentimento(convite: string) {
  const { data: c } = await db.from("config").select("valor").eq("chave", "yt_convite").maybeSingle();
  if (!c?.valor || convite !== c.valor) return { erro: "convite inválido" };
  const state = crypto.randomUUID();
  await db.from("config").upsert({ chave: "yt_state", valor: state, atualizado: new Date().toISOString() });
  const u = new URL("https://accounts.google.com/o/oauth2/v2/auth");
  u.search = new URLSearchParams({
    client_id: YT_CLIENT_ID, redirect_uri: YT_REDIRECT, response_type: "code", state,
    scope: "https://www.googleapis.com/auth/youtube.upload", access_type: "offline", prompt: "consent select_account",
  }).toString();
  return { url: u.toString() };
}

async function segredoYoutube() {
  const { data, error } = await db.rpc("segredo_youtube");
  if (error || !data) throw new Error("YouTube: chave secreta não está no cofre (youtube_client_secret)");
  return String(data);
}

async function youtubeCallback(code: string, state: string) {
  const { data: st } = await db.from("config").select("valor,atualizado").eq("chave", "yt_state").maybeSingle();
  if (!st?.valor || st.valor !== state || Date.now() - new Date(st.atualizado).getTime() > 20 * 60_000) return { erro: "link expirado; comece de novo pelo convite" };
  await db.from("config").delete().eq("chave", "yt_state");
  const r = await fetch(GOOGLE_TOKEN, {
    method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ code, client_id: YT_CLIENT_ID, client_secret: await segredoYoutube(), redirect_uri: YT_REDIRECT, grant_type: "authorization_code" }),
  });
  const j = await r.json();
  if (!j.refresh_token) return { erro: "Google não devolveu o acesso: " + JSON.stringify(j.error_description ?? j.error ?? j).slice(0, 200) };
  await db.from("config").upsert({ chave: "yt_refresh", valor: j.refresh_token, atualizado: new Date().toISOString() });
  return { ok: true };
}

async function youtubeAcesso() {
  const { data: c } = await db.from("config").select("valor").eq("chave", "yt_refresh").maybeSingle();
  if (!c?.valor) return null;
  const r = await fetch(GOOGLE_TOKEN, {
    method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ refresh_token: c.valor, client_id: YT_CLIENT_ID, client_secret: await segredoYoutube(), grant_type: "refresh_token" }),
  });
  const j = await r.json();
  if (!j.access_token) throw new Error("YouTube: não consegui renovar o acesso: " + JSON.stringify(j).slice(0, 200));
  return j.access_token as string;
}

async function youtubeEnviar(p: Record<string, any>, videoUrl: string) {
  const token = await youtubeAcesso();
  if (!token) return null; // canal ainda não conectado
  const nome = String(p.titulo_curto ?? p.titulo).slice(0, 80);
  const link = await linkRastreado(p as { id: number; link_afiliado: string }, "yt", "shorts");
  const descricao = [
    (p.legenda ?? nome) + " #publi",
    "",
    `🛒 Link do produto (Achado #${p.id}): ${link}`,
    "⚠️ Preço e estoque podem mudar. Link de afiliado: posso ganhar comissão, sem custo extra para você.",
    "",
    "#shorts #achadinhos #shopee #achadosdashopee",
  ].join("\n");
  const meta = {
    snippet: { title: `${nome} #shorts`, description: descricao.slice(0, 4900), categoryId: "26", defaultLanguage: "pt-BR", defaultAudioLanguage: "pt-BR", tags: ["achadinhos", "shopee", "achados da shopee", String(p.categoria ?? "").toLowerCase()].filter(Boolean) },
    status: { privacyStatus: "public", selfDeclaredMadeForKids: false },
  };
  const bytes = new Uint8Array(await (await fetch(videoUrl)).arrayBuffer());
  const ini = await fetch("https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status", {
    method: "POST",
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json; charset=UTF-8", "X-Upload-Content-Type": "video/mp4", "X-Upload-Content-Length": String(bytes.byteLength) },
    body: JSON.stringify(meta),
  });
  const destino = ini.headers.get("location");
  if (!destino) throw new Error("YouTube: " + (await ini.text()).slice(0, 300));
  const up = await fetch(destino, { method: "PUT", headers: { "Content-Type": "video/mp4" }, body: bytes });
  const j = await up.json();
  if (!j.id) throw new Error("YouTube: " + JSON.stringify(j).slice(0, 300));
  return { id: j.id as string, privacidade: j.status?.privacyStatus as string };
}

async function outrasRedes(produtoId: number, videoUrl: string) {
  const { data: p } = await db.from("produtos").select("*").eq("id", produtoId).single();
  if (!p) return;
  try {
    const yt = await youtubeEnviar(p, videoUrl);
    if (yt) await registrar("youtube", "ok", `youtube ${yt.privacidade} https://youtube.com/shorts/${yt.id}`, produtoId, yt.id);
  } catch (e) {
    await registrar("youtube", "erro", String(e), produtoId);
  }
}

